":"paragraph","props":{"text":"ستظهر لك صفحة تأكيد وتصلك رسالة، ونتصل بك لتأكيد طلبات الدفع عند الاستلام.","translations":{"en":{"text":"You see a confirmation page and get a message; we also call to confirm cash orders."}}},"children":[]}]},{"id":"hekaya-faq-columns-n9","type":"accordionItem","props":{"title":"هل يمكنني تعديل طلبي أو إلغاؤه؟","translations":{"en":{"title":"Can I change or cancel my order?"}}},"children":[{"id":"hekaya-faq-columns-n10","type":"paragraph","props":{"text":"نعم، حتى يتم شحنه. تواصل معنا بأسرع وقت.","translations":{"en":{"text":"Yes, until it ships. Message us as soon as you can."}}},"children":[]}]},{"id":"hekaya-faq-columns-n11","type":"accordionItem","props":{"title":"كم يستغرق التوصيل؟","translations":{"en":{"title":"How long does delivery take?"}}},"children":[{"id":"hekaya-faq-columns-n12","type":"paragraph","props":{"text":"القاهرة والجيزة من يوم إلى يومين، وباقي المحافظات من ٢ إلى ٦ أيام.","translations":{"en":{"text":"Cairo and Giza in 1 to 2 days, other governorates in 2 to 6 days."}}},"children":[]}]}]}],"style":{"background":"background","paddingTop":12,"paddingBottom":12,"paddingStart":24,"paddingEnd":24},"breakpointStyles":{"mobile":{"paddingStart":16,"paddingEnd":16}}},{"id":"hekaya-faq-columns-n13","type":"vFlex","props":{"label":"عمود","translations":{"en":{"label":"Column"}}},"children":[{"id":"hekaya-faq-columns-n14","type":"accordion","props":{"role":"items","label":"الأسئلة","translations":{"en":{"label":"Questions"}}},"children":[{"id":"hekaya-faq-columns-n15","type":"accordionItem","props":{"title":"هل التوصيل متاح لكل المحافظات؟","translations":{"en":{"title":"Do you deliver everywhere?"}}},"children":[{"id":"hekaya-faq-columns-n16","type":"paragraph","props":{"text":"نعم، نوصل لكل محافظات مصر.","translations":{"en":{"text":"Yes, we deliver to every governorate in Egypt."}}},"children":[]}]},{"id":"hekaya-faq-columns-n17","type":"accordionItem","props":{"title":"ما طرق الدفع المتاحة؟","translations":{"en":{"title":"Which payment methods do you accept?"}}},"children":[{"id":"hekaya-faq-columns-n18","type":"paragraph","props":{"text":"الدفع عند الاستلام، والبطاقات، والمحافظ الإلكترونية، وإنستاباي.","translations":{"en":{"text":"Cash on delivery, cards, mobile wallets and InstaPay."}}},"children":[]}]},{"id":"hekaya-faq-columns-n19","type":"accordionItem","props":{"title":"عرض ٣ + ١ بيشتغل إزاي؟","translations":{"en":{"title":"How does buy 3, get 1 work?"}}},"children":[{"id":"hekaya-faq-columns-n20","type":"paragraph","props":{"text":"ضيف ٤ كتب للسلة وإحنا بنخصم أرخص واحد عند التأكيد.","translations":{"en":{"text":"Add four books to your cart and we take the cheapest one off when we confirm the order."}}},"children":[]}]}]}],"style":{"background":"background","paddingTop":12,"paddingBottom":12,"paddingStart":24,"paddingEnd":24},"breakpointStyles":{"mobile":{"paddingStart":16,"paddingEnd":16}}}],"style":{"columns":2,"gap":1,"background":"border","borderWidth":1,"borderColor":"border","radius":22,"overflow":"hidden"},"breakpointStyles":{"mobile":{"columns":1}}}]}],"style":{"paddingTop":64,"paddingBottom":64},"breakpointStyles":{"mobile":{"paddingTop":40,"paddingBottom":40}}}],"source":"hekaya-faq-columns@1"}]}}]}'::jsonb,
